import{r as e}from"./jsx-runtime-BguD1OXD.js";var t=`https://learn.microsoft.com/en-us/`,n=`https://microsoftlearning.github.io/mslearn-fabric/Instructions/Labs/`,r=(e,t)=>`${n}${e}.html${t?`#${t}`:``}`,i=(e,n)=>`${t}${e}${n?`#${n}`:``}`,a={trial:`fabric/fundamentals/fabric-trial`,workspaces:`fabric/fundamentals/create-workspaces`,terminology:`fabric/fundamentals/fabric-terminology`,roles:`fabric/fundamentals/roles-workspaces`,shortcut:`fabric/onelake/shortcuts/create-onelake-shortcut`,decideLhWh:`fabric/fundamentals/decision-guide-lakehouse-warehouse`,union:`sql/t-sql/language-elements/set-operators-union-transact-sql?view=fabric`,dlOverview:`fabric/fundamentals/direct-lake-overview`,gitIntro:`fabric/cicd/git-integration/intro-to-git-integration`,catalogExplore:`fabric/governance/onelake-catalog-explore`,dataStoreGuide:`fabric/fundamentals/decision-guide-data-store`,connections:`fabric/data-factory/data-source-management`,dataflow:`fabric/data-factory/create-first-dataflow-gen2`,pipeline:`fabric/data-factory/create-first-pipeline-with-sample-data`,dataWrangler:`fabric/data-science/data-wrangler`,visualQuery:`fabric/data-warehouse/visual-query-editor`,sqlEditor:`fabric/data-warehouse/sql-query-editor`,createView:`sql/t-sql/statements/create-view-transact-sql?view=fabric`,createEventhouse:`fabric/real-time-intelligence/create-eventhouse`,ehOneLake:`fabric/real-time-intelligence/event-house-onelake-availability`,rtHub:`fabric/real-time-hub/real-time-hub-overview`,dlDevelop:`fabric/fundamentals/direct-lake-develop`,dlHow:`fabric/fundamentals/direct-lake-how-it-works`,composite:`power-bi/transform-model/desktop-composite-models`,calcGroups:`power-bi/transform-model/calculation-groups`,dfs:`power-bi/create-reports/desktop-dynamic-format-strings`,fieldParams:`power-bi/create-reports/power-bi-field-parameters`,perfAnalyzer:`power-bi/create-reports/performance-analyzer`,daxQueryView:`power-bi/transform-model/dax-query-view`,daxQueries:`dax/dax-queries`,defineStatement:`dax/define-statement-dax`,summarizecolumns:`dax/summarizecolumns-function-dax`,smRls:`fabric/security/service-admin-row-level-security`,smOls:`fabric/security/service-admin-object-level-security`,whRls:`fabric/data-warehouse/row-level-security`,whCls:`fabric/data-warehouse/column-level-security`,ddm:`fabric/data-warehouse/dynamic-data-masking`,whShare:`fabric/data-warehouse/share-warehouse-manage-permissions`,oneLakeSecurity:`fabric/onelake/security/get-started-security`,endorse:`fabric/fundamentals/endorsement-promote-certify`,labels:`fabric/fundamentals/apply-sensitivity-labels`,lineage:`fabric/governance/lineage`,impact:`fabric/governance/impact-analysis`,git:`fabric/cicd/git-integration/git-get-started`,deployStart:`fabric/cicd/deployment-pipelines/get-started-with-deployment-pipelines`,deployRules:`fabric/cicd/deployment-pipelines/create-rules`,getDesktop:`power-bi/fundamentals/desktop-get-the-desktop`,liveConnect:`power-bi/connect-data/desktop-report-lifecycle-datasets`,pbip:`power-bi/developer/projects/projects-overview`,pbipModel:`power-bi/developer/projects/projects-dataset`,pbit:`power-bi/create-reports/desktop-templates`,pbids:`power-bi/connect-data/desktop-data-sources`,sharedModels:`power-bi/connect-data/service-datasets-across-workspaces`,whConnect:`fabric/data-warehouse/how-to-connect`,incremental:`power-bi/connect-data/incremental-refresh-configure`,largeModels:`fabric/enterprise/powerbi/service-premium-large-models`,xmla:`fabric/enterprise/powerbi/service-premium-connect-tools`,smOneLake:`fabric/enterprise/powerbi/onelake-integration-overview`,webModel:`fabric/fundamentals/direct-lake-web-modeling`,editModels:`power-bi/transform-model/service-edit-data-models`,comparePipeline:`fabric/cicd/deployment-pipelines/compare-pipeline-content`,shortcuts:`fabric/onelake/onelake-shortcuts`,m2m:`power-bi/guidance/relationships-many-to-many`,relationships:`power-bi/transform-model/desktop-relationships-understand`,ctas:`sql/t-sql/statements/create-table-as-select-azure-sql-data-warehouse?view=fabric`,whModels:`fabric/data-warehouse/semantic-models`,whCreateModel:`fabric/data-warehouse/create-semantic-model`},o=`Keep your DP600-Dev workspace.`,s=[{id:`L01`,order:1,title:`Open the mill: start the trial and set up two workspaces`,goal:`Start a Fabric trial, check its size and end date, and create the two workspaces every later lab uses.`,machineIds:[`mill-lease`,`water-wheel`,`founding-charter`],bulletIds:[],platform:`browser`,minutes:30,prereqs:[],before:`You need a work or school account that can sign in to Fabric. Never paste your tenant name, account email, or any URL from your tenant into a problem note.`,steps:[{id:`s1`,text:`Start a Fabric trial from the Account manager (Method 1 on the trial page). If your organization already has a trial you can join, Learn describes that too.`,sources:[i(a.trial,`method-1-start-a-new-trial-capacity-from-the-account-manager`)],checkpoint:`The Account manager shows a trial status with a number of days left.`,trapPairId:`fabric-trial-vs-pbi-trial`,trapNote:`A Fabric trial gives you a trial capacity, not just a Power BI individual trial license.`},{id:`s2`,text:`Enter the day you started the trial on this app’s Labs page. The Account manager shows days remaining, not the start date, so use the day you did step 1.`,sources:[i(a.trial,`get-the-status-of-your-trial`)],checkpoint:`The Labs page shows days left out of 60.`},{id:`s3`,text:`Check whether your trial capacity has 4 or 64 capacity units, on the Trial tab of the capacities page (Learn gives the path). If it has 4 and you’re a capacity or tenant admin, you may be able to raise it to 64; this doesn’t add days.`,sources:[i(a.trial,`increase-trial-capacity`)],checkpoint:`You know your trial capacity’s size (4 or 64 capacity units).`},{id:`s4`,text:`Read what the trial doesn’t include and what happens when it ends. No lab in this app uses an excluded feature.`,sources:[i(a.trial,`whats-includedand-whats-not`),i(a.trial,`when-your-fabric-trial-ends`)]},{id:`s5`,text:`Create a workspace named DP600-Dev and, under Advanced, choose a license mode or workspace type that uses your trial capacity (Trial).`,sources:[i(a.workspaces,`workspace-type`),r(`21-implement-cicd`,`create-workspaces`)],checkpoint:`The workspace opens empty, and its settings show it on a trial capacity.`,trapPairId:`capacity-vs-workspace`,trapNote:`The capacity supplies compute; the workspace is the container you assign to it.`},{id:`s6`,text:`Create a second workspace named DP600-Test the same way. Lab 13 deploys from Dev to Test.`,sources:[i(a.workspaces,`workspace-type`),r(`21-implement-cicd`,`create-workspaces`)],checkpoint:`Both workspaces appear in your Workspaces list.`},{id:`s7`,text:`In DP600-Dev, open New item and browse the item types, grouped by workload. Don’t create anything yet.`,sources:[i(a.terminology)],checkpoint:`You can see item types such as Lakehouse, Warehouse, and Eventhouse.`,trapPairId:`workload-vs-item`,trapNote:`A workload (for example Data Engineering) groups item types; a lakehouse is an item.`}],cleanup:[{id:`c1`,text:`Nothing to delete yet. Keep DP600-Dev and DP600-Test for the later labs; Lab 15’s cleanup removes them.`,sources:[i(a.workspaces,`workspace-type`)]}]},{id:`L02`,order:2,title:`Thread intake: load data into a lakehouse four ways`,goal:`Get data into a lakehouse by upload, Dataflow Gen2, a pipeline Copy activity, and a shortcut; then find it in the OneLake catalog and compare data stores.`,machineIds:[`thread-intake`,`bale-catalog`,`vat-selector`,`three-vats`],bulletIds:[`P1.1`,`P1.3`,`P1.2`,`P1.4`],platform:`browser`,minutes:90,prereqs:[`L01`],before:`Work in DP600-Dev. Where an exercise says “Create a workspace”, skip that section and use DP600-Dev. Skip any optional section that needs AI features; the trial doesn’t include them.`,steps:[{id:`s1`,text:`Create a lakehouse named Mill_Lakehouse.`,sources:[r(`01-lakehouse`,`create-a-lakehouse`)],checkpoint:`The lakehouse explorer shows empty Tables and Files folders.`},{id:`s2`,text:`Download the exercise’s sample sales file and upload it to the Files folder.`,sources:[r(`01-lakehouse`,`upload-a-file`)],checkpoint:`The file appears under Files.`},{id:`s3`,text:`Load the uploaded file into a new Delta table.`,sources:[r(`01-lakehouse`,`load-file-data-into-a-table`)],checkpoint:`A new table appears under Tables, and selecting it shows rows.`},{id:`s4`,text:`Switch to the lakehouse’s SQL analytics endpoint and run a SELECT query on the new table.`,sources:[r(`01-lakehouse`,`use-sql-to-query-tables`),i(a.decideLhWh,`evaluate-each-service`)],checkpoint:`The query returns rows in the results pane.`,trapPairId:`endpoint-vs-warehouse`,trapNote:`The SQL analytics endpoint reads the lakehouse’s Delta tables; you can’t INSERT or UPDATE through it.`},{id:`s5`,text:`Create a Dataflow Gen2 that gets the exercise’s sample data, add the lakehouse as its data destination, then Save & run.`,sources:[r(`05-dataflows-gen2`,`create-a-dataflow-gen2-to-ingest-data`),r(`05-dataflows-gen2`,`add-data-destination-for-dataflow`)],checkpoint:`After the dataflow runs, a new table from it appears in the lakehouse.`},{id:`s6`,text:`Open Manage connections and gateways and find the connection your dataflow created. Look at its connection type and who can use it.`,sources:[i(a.connections,`add-a-data-source`),i(a.connections,`manage-users`)],checkpoint:`At least one connection is listed for the source you used.`},{id:`s7`,text:`Create a pipeline with a Copy data activity that copies the exercise’s file from HTTP into the lakehouse, using the exercise’s destination folder and file name (so it doesn’t overwrite your step 2 upload), then run it.`,sources:[r(`04-ingest-pipeline`,`create-a-pipeline`),r(`04-ingest-pipeline`,`configure-the-source`),r(`04-ingest-pipeline`,`configure-the-destination`),r(`04-ingest-pipeline`,`run-the-pipeline`)],checkpoint:`The pipeline run shows a Succeeded status.`,trapPairId:`dataflow-pipeline-notebook`,trapNote:`The dataflow transformed data with Power Query; the pipeline orchestrated a copy.`},{id:`s8`,optional:!0,text:`Add your dataflow as an activity in a pipeline, so the pipeline runs it. Running the dataflow again appends its rows again (its destination uses Append), so expect duplicates.`,sources:[r(`05-dataflows-gen2`,`add-a-dataflow-to-a-pipeline`)],checkpoint:`The pipeline canvas shows a Dataflow activity.`},{id:`s9`,text:`Create a second lakehouse named Mill_Shortcuts and add a OneLake shortcut in its Tables folder that points to a table in Mill_Lakehouse.`,sources:[i(a.shortcut,`create-a-shortcut`),r(`25-discover-onelake`,`create-a-shortcut-to-access-data-from-another-workspace`)],checkpoint:`The shortcut appears in Mill_Shortcuts’ Tables folder and returns the same rows as the original.`,trapPairId:`shortcut-mirror-copy`,trapNote:`A shortcut references the data in place; the Copy activity in step 7 made a copy.`},{id:`s10`,text:`Open the OneLake catalog’s Explore tab, filter to your workspace, and open an item’s details.`,sources:[i(a.catalogExplore,`open-the-explore-tab`),i(a.catalogExplore,`filter-the-items-list`),i(a.catalogExplore,`view-item-details`)],checkpoint:`The details pane shows the item’s location (your workspace).`,trapPairId:`catalog-vs-rthub`,trapNote:`The OneLake catalog finds data items; the Real-Time hub (Lab 6) finds data streams.`},{id:`s11`,text:`Read the data store decision guide’s scenarios. For each, decide which store fits (lakehouse, warehouse, eventhouse, or SQL database) and why, then compare with the guide’s answer. You build a warehouse in Lab 4 and an eventhouse in Lab 6.`,sources:[i(a.dataStoreGuide,`scenarios`)],trapPairId:`stores`,trapNote:`Lakehouse: Spark and files. Warehouse: T-SQL writes. Eventhouse: KQL on events.`}],cleanup:[{id:`c1`,text:`Delete the Mill_Shortcuts lakehouse. Deleting a shortcut doesn’t delete the target data.`,sources:[i(a.shortcuts,`how-do-shortcuts-handle-deletions`)]},{id:`c2`,text:`If you set a schedule on the pipeline, remove it so it doesn’t run on its own. Keep Mill_Lakehouse and the Copy pipeline from step 7 (name it Copy_Sales) for Lab 13; you can delete the dataflow and any second pipeline from step 8. `+o,sources:[i(a.pipeline,`run-and-schedule-your-pipeline`)]}]},{id:`L03`,order:3,title:`Carding and twisting: clean, join, and aggregate in a Spark notebook`,goal:`Use a notebook to remove duplicates, fill nulls, convert types, filter, join, aggregate, add columns, and write a Delta table.`,machineIds:[`carding-machine`,`twisting-frame`,`dye-vat`],bulletIds:[`P2.7`,`P2.8`,`P2.9`,`P2.5`,`P2.6`,`P2.2`],platform:`browser`,minutes:75,prereqs:[`L02`],before:`Work in DP600-Dev. Skip the exercise’s “Create a workspace” part, but do create its lakehouse (name it Spin_Lakehouse). Skip every optional prompt that needs AI features; the trial doesn’t include them.`,steps:[{id:`s1`,text:`Create a lakehouse named Spin_Lakehouse, import the exercise’s notebook, attach it to the lakehouse, and run the first cell to create the sample tables.`,sources:[r(`26c-transform-data-notebooks`,`create-a-workspace`),r(`26c-transform-data-notebooks`,`generate-sample-data`)],checkpoint:`The Explorer pane lists the three sample tables after a refresh.`},{id:`s2`,text:`Run the shape-and-clean cells. Note how the query removes the duplicate row, replaces the null, and adds a calculated and a conditional column.`,sources:[r(`26c-transform-data-notebooks`,`shape-and-clean-the-sales-data`)],checkpoint:`The result has fewer rows than the raw table, and no null remains in the cleaned column.`},{id:`s3`,text:`Run the join and aggregate cells.`,sources:[r(`26c-transform-data-notebooks`,`join-and-aggregate-the-data`),i(a.union,`arguments`)],checkpoint:`The summary has one row per region.`,trapPairId:`merge-vs-append`,trapNote:`A join adds columns from another table; a union stacks rows.`},{id:`s4`,text:`Run the window-function cell and compare its row count with the aggregate.`,sources:[r(`26c-transform-data-notebooks`,`apply-window-functions`)],checkpoint:`The window-function result keeps every detail row.`},{id:`s5`,text:`Write the enriched result to a Delta table and query it.`,sources:[r(`26c-transform-data-notebooks`,`write-results-to-a-delta-table`)],checkpoint:`A new table appears under Tables after a refresh.`},{id:`s6`,text:`In a new cell, load the raw sales table into a DataFrame (for example df = spark.sql("SELECT * FROM raw_sales")) and run the cell, then open Data Wrangler on df. Data Wrangler works with pandas and Spark DataFrames.`,sources:[i(a.dataWrangler,`launching-data-wrangler`)],checkpoint:`Data Wrangler opens with a Summary panel that reports missing values.`},{id:`s7`,text:`In Data Wrangler, preview and apply the operations to drop duplicate rows, fill missing values, and change a column’s type.`,sources:[i(a.dataWrangler,`browsing-data-cleaning-operations`),i(a.dataWrangler,`previewing-and-applying-operations`)],checkpoint:`Each applied operation appears as a step in the cleaning steps list.`},{id:`s8`,text:`Export the generated code back to the notebook and read it.`,sources:[i(a.dataWrangler,`saving-and-exporting-code`)],checkpoint:`A new code cell holds the generated function.`}],cleanup:[{id:`c1`,text:`Stop the notebook’s Spark session if it’s still running, then delete the notebook and Spin_Lakehouse. `+o,sources:[r(`26c-transform-data-notebooks`,`clean-up-resources`),r(`02-analyze-spark`,`clean-up-resources`)]}]},{id:`L04`,order:4,title:`Weave planner: a star schema in a warehouse with T-SQL`,goal:`In a warehouse, write T-SQL that filters, joins, and aggregates; create a view and a stored procedure; then load dimension and fact tables.`,machineIds:[`weave-planner`,`recipe-book`],bulletIds:[`P2.3`,`P2.4`,`P2.1`],platform:`browser`,minutes:90,prereqs:[`L01`],before:`Work in DP600-Dev. Skip the exercise’s “Create a workspace” part and every optional section that needs AI features (the trial doesn’t include them). Name the warehouse Mill_Warehouse; Labs 11, 14, and 15 use it.`,steps:[{id:`s1`,text:`Create a warehouse named Mill_Warehouse.`,sources:[r(`26d-transform-data-tsql`,`create-a-warehouse`)],checkpoint:`The warehouse opens with an empty Explorer.`,trapPairId:`endpoint-vs-warehouse`,trapNote:`Unlike the SQL analytics endpoint in Lab 2, a warehouse accepts INSERT, UPDATE, and CTAS.`},{id:`s2`,text:`Create the staging tables and load the sample data.`,sources:[r(`26d-transform-data-tsql`,`create-staging-tables-and-load-sample-data`)],checkpoint:`The staging schema lists the new tables in the Explorer.`},{id:`s3`,text:`Run the exercise’s T-SQL queries that filter, join, aggregate, and use window functions and a CTE.`,sources:[r(`26d-transform-data-tsql`,`transform-data-with-t-sql-queries`)],checkpoint:`Each query returns a result grid without errors.`},{id:`s4`,text:`Create the view for reusable logic and query it.`,sources:[r(`26d-transform-data-tsql`,`create-a-view-for-reusable-logic`),i(a.createView)],checkpoint:`The view appears under Views and returns rows.`},{id:`s5`,text:`Build the stored procedure with a parameter and run it.`,sources:[r(`26d-transform-data-tsql`,`build-a-stored-procedure-with-parameters`)],checkpoint:`The procedure appears under Stored Procedures and its EXEC call completes.`},{id:`s6`,text:`Create and load the date, customer, and product dimensions and the fact table. Note how the fact load looks up surrogate keys from the dimensions.`,sources:[r(`26d-transform-data-tsql`,`create-and-load-dimensional-tables`)],checkpoint:`The dim and fact schemas list the new tables, and the fact table returns rows.`,trapPairId:`star-vs-snowflake`,trapNote:`Each dimension is one flat table joined straight to the fact: a star, not a snowflake.`},{id:`s7`,text:`Run the verification queries.`,sources:[r(`26d-transform-data-tsql`,`verify-the-final-state`)],checkpoint:`Every verification query returns without errors.`},{id:`s8`,optional:!0,text:`In a separate warehouse, run the dimensional modeling exercise from “Create the fact table” through “Load sample data”, then its two slowly changing dimension sections.`,sources:[r(`26-design-dimensional-models`,`create-the-fact-table`),r(`26-design-dimensional-models`,`load-sample-data`),r(`26-design-dimensional-models`,`simulate-an-scd-type-2-change`),r(`26-design-dimensional-models`,`simulate-an-scd-type-1-change`)],checkpoint:`After the type 2 change, the changed product has more than one row, and only one is marked current.`,trapPairId:`scd1-vs-scd2`,trapNote:`Type 1 overwrites the old value; type 2 keeps history in a new row.`},{id:`s9`,optional:!0,text:`Build a many-to-many case for Lab 7: create a bridge table between the customer and product dimensions with CTAS from the fact table you loaded, for example CREATE TABLE dbo.bridge_customer_product AS SELECT DISTINCT customer_key, product_key FROM fact.sales (the dbo schema already exists). Each row says a customer bought a product, so one customer can link to many products and one product to many customers. If you reload fact.sales later, drop and re-create the bridge.`,sources:[i(a.ctas,`syntax-1`),i(a.m2m,`relate-many-to-many-dimensions`),r(`26d-transform-data-tsql`,`create-and-load-dimensional-tables`)],checkpoint:`The bridge table appears under the dbo schema with two key columns and returns rows.`}],cleanup:[{id:`c1`,text:`Keep Mill_Warehouse for Labs 11, 14, and 15. If you did step 8, delete that extra warehouse.`,sources:[r(`26-design-dimensional-models`,`clean-up-resources`)]}]},{id:`L05`,order:5,title:`Inspection bench: the Visual query editor and the SQL query editor`,goal:`Answer the same questions with the Visual query editor and with T-SQL, look at the SQL a visual query generates, and save a result as a view.`,machineIds:[`inspection-bench`],bulletIds:[`P3.1`,`P3.2`],platform:`browser`,minutes:45,prereqs:[`L01`],before:`Work in DP600-Dev. Skip the exercise’s “Create a workspace” part.`,steps:[{id:`s1`,text:`Create the sample warehouse described in the exercise.`,sources:[r(`06b-data-warehouse-query`,`create-a-sample-data-warehouse`)],checkpoint:`The Explorer lists the sample tables.`},{id:`s2`,text:`Run the exercise’s T-SQL queries that select, filter, group, and aggregate.`,sources:[r(`06b-data-warehouse-query`,`query-the-data-warehouse`),i(a.sqlEditor,`sql-query-editor-in-the-fabric-portal`)],checkpoint:`Each query returns a result grid.`},{id:`s3`,text:`Run the data consistency checks.`,sources:[r(`06b-data-warehouse-query`,`verify-data-consistency`)],checkpoint:`Each check query runs without errors.`},{id:`s4`,text:`Open a new visual query. Drag a table onto the canvas, keep a few columns, filter rows, and group by one column with an aggregation.`,sources:[i(a.visualQuery,`visual-query-editor-in-the-fabric-portal`)],checkpoint:`The results preview shows one row per group.`,trapPairId:`visual-vs-sql-editor`,trapNote:`The Visual query editor builds the query from steps; the SQL editor runs the T-SQL you type.`},{id:`s5`,text:`Use View SQL to see the T-SQL that your visual query generates.`,sources:[i(a.visualQuery,`view-sql`)],checkpoint:`The generated T-SQL includes a GROUP BY.`},{id:`s6`,text:`Save the visual query as a view, then save a T-SQL query as a view as the exercise shows.`,sources:[i(a.visualQuery,`save-as-view`),r(`06b-data-warehouse-query`,`save-as-view`)],checkpoint:`Both views appear under Views.`}],cleanup:[{id:`c1`,text:`Delete the sample warehouse. `+o,sources:[r(`06b-data-warehouse-query`,`clean-up-resources`)]}]},{id:`L06`,order:6,title:`Tension meter: an eventhouse, KQL, and OneLake availability`,goal:`Query an eventhouse with KQL (and its T-SQL emulation), make a KQL table available in OneLake, and browse the Real-Time hub.`,machineIds:[`tension-meter`,`shared-spool`,`bale-catalog`],bulletIds:[`P3.3`,`P1.5`,`P1.2`],platform:`browser`,minutes:60,prereqs:[`L01`],before:`Work in DP600-Dev. Skip the exercise’s “Create a workspace” part.`,steps:[{id:`s1`,text:`Create the sample eventhouse from the Real-Time Intelligence workload, as the exercise describes.`,sources:[r(`12-query-data-in-kql-database`,`create-an-eventhouse`)],checkpoint:`The eventhouse has a KQL database with a sample table.`},{id:`s2`,text:`Retrieve rows with take, then pick columns with project.`,sources:[r(`12-query-data-in-kql-database`,`retrieve-data-from-a-table-with-kql`)],checkpoint:`The result shows only the columns you projected.`,trapPairId:`project-vs-extend`,trapNote:`project keeps only the columns you list; extend adds columns and keeps the rest.`},{id:`s3`,text:`Summarize with sum, first overall and then by a column.`,sources:[r(`12-query-data-in-kql-database`,`summarize-data-by-using-kql`)],checkpoint:`The grouped query returns one row per group.`},{id:`s4`,text:`Sort with sort by and with order by, then filter with where.`,sources:[r(`12-query-data-in-kql-database`,`sort-data-by-using-kql`),r(`12-query-data-in-kql-database`,`filter-data-by-using-kql`)],checkpoint:`sort by and order by return the same order.`},{id:`s5`,text:`Run the exercise’s T-SQL queries against the same KQL database.`,sources:[r(`12-query-data-in-kql-database`,`query-data-by-using-transact-sql`)],checkpoint:`The T-SQL queries return results from the same table.`,trapPairId:`sql-vs-kql`,trapNote:`Same question, two languages: GROUP BY vs summarize … by, SELECT vs project.`},{id:`s6`,text:`Turn on OneLake availability for the sample table, or for the KQL database with “Apply to existing tables” selected (otherwise only new tables are included).`,sources:[i(a.ehOneLake,`turn-on-onelake-availability-for-a-kql-database-or-table`)],checkpoint:`The database details show OneLake availability as on.`,trapPairId:`onelake-availability-vs-integration`,trapNote:`This is Eventhouse OneLake availability; semantic model OneLake integration is in Lab 15.`},{id:`s7`,text:`Look at the table’s Delta files in OneLake. Learn says files can take up to a few hours to appear, so come back later if they aren’t there yet.`,sources:[i(a.ehOneLake,`view-delta-lake-files-in-onelake`)],checkpoint:`You can see a Delta folder for the table, or a note that files are still being written.`},{id:`s8`,optional:!0,text:`Query the table’s Delta data from a notebook, as Learn describes, then stop the Spark session. The OneLake path contains ids from your tenant: don’t paste it into a problem note.`,sources:[i(a.ehOneLake,`query-delta-tables-from-a-fabric-notebook`)],checkpoint:`The notebook returns rows from the table.`},{id:`s9`,text:`Open the Real-Time hub and browse its streams and sources. Don’t connect a new source.`,sources:[i(a.rtHub)],checkpoint:`The Real-Time hub page opens and lists streams or data sources.`,trapPairId:`catalog-vs-rthub`,trapNote:`Real-Time hub: streams and events. OneLake catalog: items such as lakehouses and models.`}],cleanup:[{id:`c1`,text:`Delete the eventhouse and any eventstream the sample created, so nothing keeps ingesting into your trial capacity. `+o,sources:[i(a.createEventhouse,`delete-an-eventhouse`),r(`07-real-time-Intelligence`,`clean-up-resources`)]}]}],c=`Sales Model`,l=[{id:`L07`,order:7,title:`Warp frame: build a Direct Lake semantic model`,goal:`Create a Direct Lake on OneLake semantic model from lakehouse tables, build a star schema with an inactive relationship, and write measures with variables.`,machineIds:[`warp-frame`,`punch-card-reader`,`loom-gearbox`],bulletIds:[`S1.2`,`S1.3`,`S1.4`,`S1.1`],platform:`browser`,minutes:90,prereqs:[`L01`],before:`Work in DP600-Dev. Models open in the browser in Viewing mode: switch to Editing mode before you change anything. Skip the exercise’s workspace creation and its optional section that needs AI features (the trial doesn’t include them). Name the model ${c}; Labs 8 to 15 use it.`,steps:[{id:`s1`,text:`Import the exercise’s notebook, create its lakehouse from the notebook, and run all cells to create the sample star schema tables.`,sources:[r(`15-design-semantic-model-scale`,`set-up-the-environment`)],checkpoint:`The lakehouse lists the dimension tables and the fact table under Tables.`},{id:`s2`,text:`Read when to choose Direct Lake on OneLake versus Direct Lake on SQL. This lab uses Direct Lake on OneLake; Lab 8 builds the other kind.`,sources:[i(a.dlDevelop,`choose-the-right-storage-mode`),i(a.dlOverview,`comparison-of-storage-modes`)],trapPairId:`storage-modes`,trapNote:`Direct Lake reads Delta tables in OneLake; Import copies data into the model; DirectQuery queries the source each time.`},{id:`s3`,text:`Open the lakehouse’s SQL analytics endpoint and choose New semantic model. Name it ${c}, pick the exercise’s four tables, and choose Direct Lake on OneLake if the dialog asks. (The exercise starts from the lakehouse explorer instead; Learn shows both entry points.)`,sources:[i(a.dlDevelop,`create-the-model`),r(`15-design-semantic-model-scale`,`create-a-semantic-model`)],checkpoint:`The model opens in the browser’s model editor with the four tables. If it says tables don’t exist or can’t refresh, wait a few minutes for the tables to sync, delete the model, and create it again.`,trapPairId:`dl-onelake-vs-sql`,trapNote:`Starting from the SQL analytics endpoint doesn’t make the model Direct Lake on SQL; the dialog choice decides.`},{id:`s4`,text:`Create the exercise’s four relationships: three active many-to-one relationships from the fact table to the dimensions, and a fourth on the ship date key to the date table with “Make this relationship active” cleared.`,sources:[r(`15-design-semantic-model-scale`,`design-star-schema-relationships`),i(a.editModels,`create-a-relationship`)],checkpoint:`The relationships list shows four relationships, and the ship-date one is inactive.`,trapPairId:`regular-vs-limited`,trapNote:`These are regular one-to-many relationships within one source group.`},{id:`s5`,text:`Create the four measures, including the two that use variables.`,sources:[r(`15-design-semantic-model-scale`,`create-measures`)],checkpoint:`The fact table shows four measures with calculator icons.`},{id:`s6`,text:`Create the ship-date measure that uses USERELATIONSHIP to activate the inactive relationship.`,sources:[r(`15-design-semantic-model-scale`,`use-userelationship-for-the-inactive-ship-date-relationship`)],checkpoint:`The measure saves without an error.`},{id:`s7`,text:`Create a report from the model and build the bar chart, card, and year slicer from the exercise. Skip the calculation group step; that’s in Lab 9. Save the report as Sales Report in DP600-Dev: Labs 9 to 11 use it.`,sources:[r(`15-design-semantic-model-scale`,`validate-the-model-with-a-report`)],checkpoint:`The order-date and ship-date measures show different values for at least one slicer range.`},{id:`s8`,optional:!0,text:`Needs Lab 4 step 9. Open Mill_Warehouse, select New semantic model, name it Bridge Model, pick the customer dimension, the bridge table, the product dimension, and the sales fact table, then Confirm and switch to Editing mode. Relate customer to bridge and product to bridge as one-to-many on the key columns, and product to the fact table as one-to-many. Don’t relate the customer dimension to the fact (that would give a second, ambiguous filter path), and don’t relate the two dimensions with a many-to-many relationship. Set the product-to-bridge relationship’s cross-filter direction to Both so a customer filter reaches the fact table, then hide the bridge table and the key columns, including the fact’s customer key. Note what the result means: a customer’s value is the sales of the products that customer bought, by any customer, not the customer’s own purchases. A real bridge is needed when the fact doesn’t carry the other key, as in Learn’s accounts-and-customers example.`,sources:[i(a.whCreateModel,`create-a-new-power-bi-semantic-model-in-direct-lake-mode`),i(a.m2m,`relate-many-to-many-dimensions-guidance`),i(a.m2m,`relate-many-to-many-dimensions`),i(a.relationships,`cross-filter-direction`),i(a.relationships,`resolve-relationship-path-ambiguity`),i(a.editModels,`create-a-relationship`)],checkpoint:`In a table of customer name and the sum of the sales amount, values differ per customer, and the customer rows can add up to more than the total: they’re non-additive, as Learn’s bank-account example explains.`,trapPairId:`regular-vs-limited`,trapNote:`One-to-many relationships between tables from one source stay regular relationships; Learn advises against relating the two dimensions with a many-to-many relationship.`}],cleanup:[{id:`c1`,text:`Stop the notebook’s Spark session. If you did step 8, delete Bridge Model (keep the bridge table in Mill_Warehouse). Keep ${c}, Sales Report, the lakehouse, and the notebook for Labs 8 to 15. Skip the exercise’s query scale-out setting.`,sources:[r(`02-analyze-spark`,`clean-up-resources`),r(`15-design-semantic-model-scale`,`configure-settings-for-scale`)]}]},{id:`L08`,order:8,title:`Direct Lake shuttle: two flavors, fallback, and a composite model`,goal:`Build a Direct Lake on SQL model next to your Direct Lake on OneLake model, see a SQL view fall back, change Direct Lake behavior, check refresh settings, and add an Import table to make a composite model.`,machineIds:[`direct-lake-shuttle`,`double-loom`,`loom-gearbox`],bulletIds:[`S2.3`,`S2.4`,`S1.7`,`S1.1`],platform:`browser`,minutes:75,prereqs:[`L07`],before:`Work in DP600-Dev with the lakehouse and ${c} from Lab 7. UI labels in the browser model editor change often; if one doesn’t match, use the cited section and report it.`,steps:[{id:`s1`,text:`In the lakehouse’s SQL analytics endpoint, create a view over the fact table joined to the product dimension. Include the product key column so step 7 can relate it, plus any other columns you like.`,sources:[i(a.createView),i(a.sqlEditor,`sql-query-editor-in-the-fabric-portal`)],checkpoint:`The view appears under Views and returns rows.`},{id:`s2`,text:`From the SQL analytics endpoint, create a second semantic model named Sales Model SQL. This time choose Direct Lake on SQL, and include one dimension table and your view.`,sources:[i(a.dlDevelop,`create-the-model`),i(a.dlDevelop,`model-tables`)],checkpoint:`The new model lists the dimension table and the view.`,trapPairId:`dl-onelake-vs-sql`,trapNote:`Only Direct Lake on SQL can use a SQL view as a Direct Lake table, and only by falling back to DirectQuery.`},{id:`s3`,text:`Writing DAX queries in the browser needs the workspace setting “User can edit data models in the Power BI service (preview)”; turn it on in DP600-Dev’s settings if it’s off. Then choose Write DAX queries from Sales Model SQL’s menu and run EVALUATE TABLETRAITS().`,sources:[i(a.dlHow,`diagnose-fallback`),i(a.daxQueryView,`dax-query-view-in-web`),i(a.daxQueryView,`considerations-and-limitations`)],checkpoint:`The DirectLakeFallbackInfo column shows None for the dimension table and a fallback reason for the view.`,trapPairId:`dl-fallback`,trapNote:`Queries on the view table fall back to DirectQuery; the plain table stays in Direct Lake.`},{id:`s4`,text:`Open Sales Model SQL in Editing mode and, in model view, change its Direct Lake behavior from Automatic to Direct Lake only (the setting applies only to Direct Lake on SQL). Query the view table again, then change it back to Automatic.`,sources:[i(a.dlHow,`control-fallback-with-directlakebehavior`)],checkpoint:`With Direct Lake only, a query on the view table returns an error instead of falling back.`},{id:`s5`,text:`Open ${c}’s settings and find “Keep your Direct Lake data up to date”. Then refresh the model manually and look at its refresh history.`,sources:[i(a.dlHow,`automatic-updates`),i(a.dlHow,`framing`)],checkpoint:`The refresh history lists your manual refresh.`,trapPairId:`framing-vs-import-refresh`,trapNote:`A Direct Lake refresh frames metadata; it doesn’t copy data like an Import refresh.`},{id:`s6`,text:`Open ${c} (Direct Lake on OneLake) in Editing mode, choose Get data on the ribbon, and add your SQL view from the SQL analytics endpoint as an Import table. Only the model’s owner can use Get data, and you may be asked to set credentials. The connection shows a server name from your tenant: don’t paste it into a problem note.`,sources:[i(a.webModel,`composite-semantic-models-with-direct-lake-and-import-storage-mode-tables`),i(a.editModels,`get-data`),i(a.editModels,`permissions`),i(a.composite,`create-composite-models-in-web-modeling`)],checkpoint:`The new table shows Import storage mode while the others show Direct Lake.`,trapPairId:`storage-modes`,trapNote:`Direct Lake plus Import in one model is a composite model; Direct Lake on SQL tables can’t join one.`},{id:`s7`,text:`Relate the Import table to a dimension and build a visual that uses columns from both storage modes.`,sources:[i(a.composite,`source-groups`),i(a.composite,`use-composite-models`)],checkpoint:`The visual returns values from both tables.`}],cleanup:[{id:`c1`,text:`Delete Sales Model SQL. Remove the Import table from ${c} so Labs 9 and 10 start from Direct Lake only. Keep the view.`,sources:[r(`15-design-semantic-model-scale`,`configure-settings-for-scale`),i(a.webModel,`composite-semantic-models-with-direct-lake-and-import-storage-mode-tables`)]}]},{id:`L09`,order:9,title:`Jacquard head: calculation groups, dynamic format strings, field parameters`,goal:`Add a time-intelligence calculation group with a dynamic format string, give a measure a dynamic format string, and (on Windows) build DAX calculations and a field parameter in Power BI Desktop.`,machineIds:[`jacquard-head`,`punch-card-reader`],bulletIds:[`S1.5`,`S1.4`],platform:`mixed`,minutes:90,prereqs:[`L07`],before:`Steps 1 to 4 run in the browser on ${c}. Steps 5 to 8 need Power BI Desktop on Windows; on a Mac, skip them and mark the lab complete without them.`,steps:[{id:`s1`,text:`In ${c}, create the exercise’s calculation group with its six calculation items.`,sources:[r(`15-design-semantic-model-scale`,`create-a-calculation-group`),i(a.calcGroups,`add-a-new-calculation-group-in-model-view`)],checkpoint:`The calculation group shows six calculation items.`},{id:`s2`,text:`Give the year-over-year item a dynamic format string, as the exercise shows.`,sources:[r(`15-design-semantic-model-scale`,`create-a-calculation-group`),i(a.calcGroups,`add-a-dynamic-format-string-to-a-calculation-item`)],checkpoint:`The item’s properties show a dynamic format string.`},{id:`s3`,text:`In Sales Report, put the calculation group’s column in the bar chart’s legend.`,sources:[r(`15-design-semantic-model-scale`,`validate-the-model-with-a-report`),i(a.calcGroups,`using-the-calculation-group-in-reports`)],checkpoint:`The legend lists the six calculation items.`,trapPairId:`calcgroup-vs-fieldparam`,trapNote:`A calculation group changes how measures are calculated; a field parameter (step 8) swaps which fields a visual shows.`},{id:`s4`,text:`Give the Profit Margin measure a dynamic format string: select the measure, set its format to Dynamic, and enter a DAX expression that returns a format string, for example IF([Profit Margin] < 0.1, "0.00%", "0.0%"). The browser’s labels may differ from Learn’s Desktop ribbon. With a calculation group in the model, Learn warns that measures become variant and some dynamic format strings can show errors; if that happens, report it.`,sources:[i(a.dfs,`create-dynamic-format-strings`),i(a.calcGroups,`model-measures-change-to-variant-data-type`)],checkpoint:`The measure still sorts as a number in a table visual, and its display format changes.`,trapPairId:`dfs-vs-format`,trapNote:`A dynamic format string keeps the number type; FORMAT() turns the value into text.`},{id:`s5`,windows:!0,text:`Install Power BI Desktop if you don’t have it, then download and open the DAX calculations exercise’s starter file.`,sources:[i(a.getDesktop,`install-as-an-app-from-the-microsoft-store`),r(`14-create-dax-calculations`,`get-started`)],checkpoint:`The starter report opens in Power BI Desktop.`},{id:`s6`,windows:!0,text:`Create the calculated table, the Date table and its calculated columns, complete the Date table (hierarchy and relationships), then mark it as a date table.`,sources:[r(`14-create-dax-calculations`,`create-the-salesperson-calculated-table`),r(`14-create-dax-calculations`,`create-the-date-table`),r(`14-create-dax-calculations`,`create-calculated-columns`),r(`14-create-dax-calculations`,`complete-the-date-table`),r(`14-create-dax-calculations`,`mark-the-date-table`)],checkpoint:`Mark as date table shows On, with the Date column selected.`},{id:`s7`,windows:!0,text:`Create the simple and additional measures, including the one that uses HASONEVALUE.`,sources:[r(`14-create-dax-calculations`,`create-simple-measures`),r(`14-create-dax-calculations`,`create-additional-measures`)],checkpoint:`The HASONEVALUE measure is blank on the table’s total row.`,trapPairId:`hasonevalue-vs-isinscope`,trapNote:`HASONEVALUE tests the filter; ISINSCOPE tests whether a column is a grouping level.`},{id:`s8`,windows:!0,text:`Create a field parameter with two or three measures, add it to a slicer, and use it in a visual.`,sources:[i(a.fieldParams,`create-a-field-parameter`),i(a.fieldParams,`use-a-field-parameter-in-a-slicer`)],checkpoint:`Choosing a field in the slicer changes the measure the visual shows.`}],cleanup:[{id:`c1`,text:`Keep the calculation group in ${c}. If you did the Windows steps, keep the starter file for Lab 14 (save it once).`,sources:[i(a.calcGroups,`considerations`)]}]},{id:`L10`,order:10,title:`Speed governor: Performance analyzer, DAX query view, and faster DAX`,goal:`Record visual timings, copy a visual’s query into DAX query view, write DAX queries that select, filter, and aggregate, and (on Windows) fix a slow measure.`,machineIds:[`speed-governor`,`dax-scale`],bulletIds:[`S2.1`,`S2.2`,`P3.4`],platform:`mixed`,minutes:75,prereqs:[`L07`],before:`Steps 1 to 5 run in the browser on a report over ${c}. Steps 6 to 9 need Power BI Desktop on Windows; on a Mac, skip them.`,steps:[{id:`s1`,text:`Open Sales Report in edit mode, open the Performance analyzer pane, start recording, and refresh the visuals.`,sources:[i(a.perfAnalyzer,`display-the-performance-analyzer-pane-in-the-web`),i(a.perfAnalyzer,`use-performance-analyzer`)],checkpoint:`Each visual shows a duration, split into categories.`,trapPairId:`perf-categories`,trapNote:`DAX query time is the engine; visual display time is rendering. Fix the bigger one.`},{id:`s2`,text:`Copy one visual’s query. Choose Write DAX queries from the model’s menu (it needs the workspace setting from Lab 8 step 3), paste the query into a new tab, and run it.`,sources:[i(a.perfAnalyzer,`dax-queries-in-visuals`),i(a.daxQueryView,`dax-query-view-in-web`)],checkpoint:`The results grid returns the same numbers the visual shows.`},{id:`s3`,text:`Write your own query: EVALUATE SUMMARIZECOLUMNS with the product category column and the Total Sales measure, ordered by sales.`,sources:[i(a.summarizecolumns),i(a.daxQueries)],checkpoint:`The grid shows one row per category.`},{id:`s4`,text:`Add a filter to the query (for example, a single year from the date table), then add a query-scoped measure with DEFINE MEASURE and use it in the same query.`,sources:[i(a.defineStatement),i(a.summarizecolumns)],checkpoint:`The query runs, and the query-scoped measure doesn’t appear in the model’s Data pane.`,trapPairId:`query-measure-vs-model-measure`,trapNote:`A DEFINE MEASURE exists only for that query until you choose to add it to the model.`},{id:`s5`,text:`Back in the report, select a bar or slicer value while recording, and compare the new entries in Performance analyzer.`,sources:[i(a.perfAnalyzer,`use-performance-analyzer`)],checkpoint:`Performance analyzer logs a new entry for the interaction.`},{id:`s6`,windows:!0,text:`Download and open the performance exercise’s starter file in Power BI Desktop, and capture a baseline.`,sources:[r(`16-optimize-semantic-model-performance`,`before-you-start`),r(`16-optimize-semantic-model-performance`,`capture-a-performance-baseline`)],checkpoint:`Performance analyzer lists the page’s visuals with durations.`},{id:`s7`,windows:!0,text:`Send the slow visual’s query to DAX query view, find the repeated expression, and rewrite the measure with a variable.`,sources:[r(`16-optimize-semantic-model-performance`,`analyze-the-slow-dax-query`),r(`16-optimize-semantic-model-performance`,`optimize-the-dax-measure`)],checkpoint:`The rewritten measure returns the same values as before.`},{id:`s8`,windows:!0,text:`Run the COLUMNSTATISTICS query and find the highest-cardinality columns.`,sources:[r(`16-optimize-semantic-model-performance`,`examine-column-cardinality`)],checkpoint:`The grid lists columns sorted by cardinality.`},{id:`s9`,windows:!0,text:`Record again and compare with your baseline.`,sources:[r(`16-optimize-semantic-model-performance`,`verify-the-improvements`)],checkpoint:`You have a second set of timings to compare (the difference may be small).`}],cleanup:[{id:`c1`,text:`Close the DAX query view tabs you don’t need. Close the Windows starter file without saving.`,sources:[r(`16-optimize-semantic-model-performance`,`clean-up-resources`)]}]}],u=`Optional: needs a second account in your organization. Without one, skip it and read the exercise’s description of what that user sees.`,d=[{id:`L11`,order:11,title:`Gatehouse: workspace roles, item permissions, and data-level security`,goal:`Review workspace roles and item permissions, then apply dynamic data masking, row-level security, and column-level security in a warehouse, a OneLake security role in a lakehouse, and a semantic model RLS role.`,machineIds:[`gate-keys`,`item-locks`,`thread-sieves`],bulletIds:[`M1.1`,`M1.2`,`M1.3`],platform:`browser`,minutes:90,prereqs:[`L02`,`L04`,`L07`],before:`Work in DP600-Dev. Step 9 is an optional Windows step; the rest runs in a browser. Create a new warehouse named Secure_Warehouse for the T-SQL parts, so Mill_Warehouse stays clean. Steps marked optional need a second account; you can finish the lab without them. Never put a real user name or email in a problem note.`,steps:[{id:`s1`,text:`Open Manage access for DP600-Dev and compare the four workspace roles with Learn’s roles table.`,sources:[i(a.workspaces,`give-users-access-to-your-workspace`),i(a.roles)],checkpoint:`You’re listed with the Admin role.`,trapPairId:`member-vs-contributor`,trapNote:`Member can add people and share; Contributor can create and edit content but can’t manage access, and can share an item only with Reshare permission.`},{id:`s2`,optional:!0,text:`Add a second user as Viewer, then check what they see from a private browser window. ${u}`,sources:[r(`19-secure-data-access`,`apply-workspace-access-controls`)],checkpoint:`The second user sees the workspace items but can’t create items.`},{id:`s3`,text:`Open Manage permissions on Mill_Warehouse (Lab 4) and look at the share options (Read, ReadData, ReadAll). Optional: share it with a second user with ReadData only.`,sources:[r(`19-secure-data-access`,`apply-item-access-control`),i(a.whShare,`share-a-warehouse`)],checkpoint:`The share dialog lists the additional permissions you can grant.`,trapPairId:`access-layers`,trapNote:`Item permissions open one item; workspace roles open every item; RLS, CLS, and OLS narrow what’s inside.`},{id:`s4`,text:`Create Secure_Warehouse and run the dynamic data masking script.`,sources:[r(`06d-secure-data-warehouse`,`apply-dynamic-data-masking-rules-to-columns-in-a-table`),i(a.ddm,`permissions-for-dynamic-data-masking`)],checkpoint:`Your own SELECT returns unmasked values, because Admin has CONTROL on the warehouse.`,trapPairId:`cls-vs-ols-vs-ddm`,trapNote:`Masking hides values from users without UNMASK or CONTROL, but the column still returns.`},{id:`s5`,text:`Run the row-level security script. Use your own sign-in name for one sales rep and a made-up name for the other.`,sources:[r(`06d-secure-data-warehouse`,`apply-row-level-security`),i(a.whRls,`predicate-based-row-level-security`)],checkpoint:`After the policy is on, your SELECT returns only your own rows, even though you’re Admin.`},{id:`s6`,optional:!0,text:`Run the column-level security and granular permission scripts against your second user. ${u}`,sources:[r(`06d-secure-data-warehouse`,`implement-column-level-security`),r(`06d-secure-data-warehouse`,`configure-sql-granular-permissions-using-t-sql`),i(a.whCls,`restrict-access-to-certain-columns-to-certain-users`)],checkpoint:`A query by that user that includes the restricted column fails with a permission error.`},{id:`s7`,text:`In a lakehouse, create a OneLake security role that grants read on one folder or table only. If your lakehouse doesn’t offer OneLake security roles, report it and continue.`,sources:[r(`19-secure-data-access`,`apply-onelake-security-in-a-lakehouse`),i(a.oneLakeSecurity,`manage-data-access-with-onelake-security-roles`)],checkpoint:`The role lists the folder or table you chose.`},{id:`s8`,text:`Open Sales Model in Editing mode, choose Manage roles, and create a role whose filter keeps one product category. Then, from the model’s Security page, use Test as role.`,sources:[i(a.editModels,`define-row-level-security-roles-and-rules`),i(a.smRls,`validate-the-role-within-the-power-bi-service`)],checkpoint:`While testing as the role, Sales Report shows only the category you kept.`},{id:`s9`,optional:!0,windows:!0,text:`Open the model security exercise’s starter file in Power BI Desktop and create one of its static roles. Then, in TMDL view, add object-level security for one column to a new role, so the static role you just made stays as it is.`,sources:[r(`17-enforce-model-security`,`set-up-the-environment`),r(`17-enforce-model-security`,`create-static-roles`),i(a.smOls,`configure-object-level-security-by-using-tmdl-view`)],checkpoint:`With View as on that role, a visual that uses the secured column no longer shows its data.`}],cleanup:[{id:`c1`,text:`Delete Secure_Warehouse. Delete the OneLake security role.`,sources:[r(`06d-secure-data-warehouse`,`clean-up-resources`)]},{id:`c2`,text:`Delete the RLS role from Sales Model, and remove any second user you added to the workspace or items.`,sources:[i(a.editModels,`define-row-level-security-roles-and-rules`),i(a.workspaces,`give-users-access-to-your-workspace`)]}]},{id:`L12`,order:12,title:`Seal and stamp: endorsement, labels, lineage, and impact analysis`,goal:`Promote and describe items, apply a sensitivity label if your tenant has labels, trace lineage, and run impact analysis on a lakehouse.`,machineIds:[`seal-and-stamp`,`ripple-map`],bulletIds:[`M1.5`,`M1.4`,`M2.4`],platform:`browser`,minutes:45,prereqs:[`L07`],before:`Work in DP600-Dev, using the lakehouse and Sales Model from Lab 7 in place of the exercise’s own items. Skip the exercise’s setup section.`,steps:[{id:`s1`,text:`Promote the lakehouse and add a description, as the exercise shows.`,sources:[r(`19b-govern-analytics-data`,`endorse-and-document-the-lakehouse`),i(a.endorse,`promote-items`)],checkpoint:`The lakehouse shows a Promoted badge in the workspace list.`},{id:`s2`,text:`Promote Sales Model and add a description.`,sources:[r(`19b-govern-analytics-data`,`endorse-and-document-the-semantic-model`)],checkpoint:`The model shows a Promoted badge.`},{id:`s3`,text:`Read how certification works. Try Certified only if your admin made you an authorized reviewer, and don’t send a certification request.`,sources:[i(a.endorse,`certify-items`)],checkpoint:`You can tell whether the Certified option is available to you.`},{id:`s4`,text:`Apply a sensitivity label to Sales Model. If your tenant has no labels, or the label menu is greyed out, report that here; that’s an expected outcome.`,sources:[i(a.labels,`prerequisites`),i(a.labels,`apply-a-label`)],checkpoint:`The label shows in the item header, or you’ve recorded that labels aren’t available.`,trapPairId:`endorse-vs-label`,trapNote:`Endorsement says the item is trustworthy; a sensitivity label says how sensitive it is.`},{id:`s5`,text:`Explore your items in the OneLake catalog as the exercise shows.`,sources:[r(`19b-govern-analytics-data`,`explore-governance-in-the-onelake-catalog`)],checkpoint:`The lakehouse details show the description you added.`},{id:`s6`,text:`Open the workspace’s lineage view and highlight the lakehouse’s lineage.`,sources:[i(a.lineage,`open-lineage-view`),i(a.lineage,`highlight-an-items-lineage`),r(`19b-govern-analytics-data`,`view-lineage-and-run-impact-analysis`)],checkpoint:`Arrows connect the lakehouse to Sales Model, directly or through its SQL analytics endpoint.`},{id:`s7`,text:`Open impact analysis for the lakehouse and look at the All downstream items tab. Don’t use Notify contacts; it sends real emails.`,sources:[i(a.impact,`open-impact-analysis-for-an-item`),i(a.impact,`impact-analysis-pane`)],checkpoint:`The pane counts downstream items and lists Sales Model among them.`,trapPairId:`lineage-vs-impact`,trapNote:`Lineage shows the whole flow; impact analysis lists what’s downstream of one item.`}],cleanup:[{id:`c1`,text:`Nothing to delete. You can leave the endorsements, descriptions, and label in place.`,sources:[r(`19b-govern-analytics-data`,`clean-up-resources`)]}]},{id:`L13`,order:13,title:`Pattern ledger and conveyor: Git integration and a deployment pipeline`,goal:`Connect DP600-Dev to a GitHub repository, commit and update, then deploy items from Dev to Test with a deployment pipeline.`,machineIds:[`pattern-ledger`,`conveyor`],bulletIds:[`M2.1`,`M2.3`],platform:`browser`,minutes:90,prereqs:[`L02`,`L07`],before:`You need a free GitHub account. You’ll create a personal access token: paste it only into Fabric, never into a problem note or anywhere in this app. If a tenant switch for Git integration is off and you can’t turn it on, report it and skip to step 7.`,steps:[{id:`s1`,text:`Check the Fabric and Git prerequisites, including the tenant switches for syncing with GitHub.`,sources:[i(a.git,`fabric-prerequisites`),i(a.git,`git-prerequisites`)],checkpoint:`You know whether the GitHub switch is on in your tenant.`},{id:`s2`,text:`Create a private GitHub repository with a README and a fine-grained token with Contents read and write on that repository only. Don’t paste the repository URL or the token into a problem note.`,sources:[i(a.git,`git-prerequisites`)],checkpoint:`The token page lists your repository with Contents: read and write.`},{id:`s3`,text:`Connect DP600-Dev to the repository’s main branch from workspace settings, and type a new folder name so the Git side starts empty. During the initial sync, content is copied from the nonempty side to the empty one; item types Git integration doesn’t support are ignored.`,sources:[i(a.git,`connect-to-a-git-repo`),i(a.git,`connect-to-a-workspace`),i(a.gitIntro,`supported-items`)],checkpoint:`Each supported item shows Synced, and the new folder in the repository has a folder per item.`},{id:`s5`,text:`Change an item in the workspace (for example, a cell in the Lab 7 notebook) and commit again. Then edit a file for another item in GitHub and use Update in Fabric.`,sources:[i(a.git,`commit-changes-to-git`),i(a.git,`update-workspace-from-git`)],checkpoint:`The GitHub edit appears in the workspace item after Update.`,trapPairId:`commit-vs-update`,trapNote:`Commit sends workspace changes to Git; Update brings Git changes into the workspace.`},{id:`s6`,text:`Disconnect the workspace from Git.`,sources:[i(a.git,`disconnect-a-workspace-from-git`)],checkpoint:`Workspace settings > Git integration shows the workspace isn’t connected.`},{id:`s7`,text:`Create a deployment pipeline. While you name it, delete the Production stage so it has only Development and Test; the number of stages can’t change after you create it.`,sources:[i(a.deployStart,`step-1---create-a-deployment-pipeline`),i(a.deployStart,`step-2---name-the-pipeline-and-assign-stages`),r(`21b-manage-semantic-model-lifecycle`,`create-a-deployment-pipeline`)],checkpoint:`The pipeline shows two stages.`,trapPairId:`pipelines-vs-git`,trapNote:`Git tracks versions of one workspace; a deployment pipeline copies content between workspaces.`},{id:`s8`,text:`Assign DP600-Dev to Development and DP600-Test to Test.`,sources:[i(a.deployStart,`step-3---assign-a-workspace`),r(`21-implement-cicd`,`assign-workspaces-to-stages-of-a-deployment-pipeline`)],checkpoint:`Each stage shows its workspace name.`},{id:`s9`,text:`Select only Mill_Lakehouse and the Copy_Sales pipeline from Lab 2, and deploy them to Test.`,sources:[i(a.deployStart,`step-5---deploy-to-an-empty-stage`),r(`21-implement-cicd`,`deploy-content-between-stages`)],checkpoint:`The deployed items appear in DP600-Test and show Same as source in the comparison (the stage may still show a difference for items you didn’t deploy).`},{id:`s10`,text:`Change the pipeline in Dev (for example, rename its Copy activity) and save it, then compare the stages before deploying again.`,sources:[i(a.comparePipeline,`compare-stages`),i(a.deployStart,`step-6---deploy-content-from-one-stage-to-another`)],checkpoint:`The comparison marks the changed item as different until you deploy.`},{id:`s11`,optional:!0,text:`Read which item types support deployment rules. A lakehouse and a pipeline aren’t among them, so there’s nothing to create here; note which items you would use rules for.`,sources:[i(a.deployRules,`create-a-deployment-rule`),i(a.deployRules,`considerations-and-limitations`)]}],cleanup:[{id:`c1`,text:`Delete the deployment pipeline, and delete the items it deployed to DP600-Test.`,sources:[r(`21-implement-cicd`,`clean-up`)]},{id:`c2`,text:`In GitHub, delete the token and the repository.`,sources:[i(a.git,`git-prerequisites`)]}]},{id:`L14`,order:14,title:`Draft table and pattern book: .pbip, .pbit, .pbids, and shared models`,goal:`Save a Power BI project and look at its files, export a template, create a data source file, and build reports on a shared semantic model.`,machineIds:[`draft-table`,`pattern-book`],bulletIds:[`M2.2`,`M2.6`],platform:`windows`,minutes:75,prereqs:[`L04`,`L07`],before:`Needs Power BI Desktop on Windows, except step 7. The .pbids file names your warehouse’s server: keep it on your computer and never paste its contents into a problem note.`,steps:[{id:`s1`,windows:!0,text:`Open the starter file from Lab 9 (or download it from the DAX calculations exercise) and save it as a Power BI project (.pbip).`,sources:[i(a.pbip,`save-as-a-project`),r(`14-create-dax-calculations`,`get-started`)],checkpoint:`The title bar shows you’re working in a project.`,trapPairId:`pbi-files`,trapNote:`.pbix is one binary file; .pbip is a folder of text files; .pbit is a template; .pbids is a connection.`},{id:`s2`,windows:!0,text:`Open the project folder and find the .Report and .SemanticModel folders. If the model is saved in TMDL format, its definition folder holds a tables subfolder with one .tmdl file per table.`,sources:[i(a.pbip,`navigate-to-files`),i(a.pbipModel,`semantic-model-files`)],checkpoint:`You can find the model definition files (TMDL files, or a single model file in the older format).`},{id:`s3`,optional:!0,windows:!0,text:`Close Desktop, change a measure’s description in its .tmdl file with a text editor, and reopen the project.`,sources:[i(a.pbipModel,`make-external-changes-to-tmdl-files`),i(a.pbip,`changes-outside-power-bi-desktop`)],checkpoint:`Desktop shows the new description.`},{id:`s4`,windows:!0,text:`Export the report as a Power BI template (.pbit), then open the template.`,sources:[i(a.pbit,`creating-report-templates`),i(a.pbit,`using-report-templates`)],checkpoint:`Opening the .pbit starts a new untitled report with the same pages and model.`},{id:`s5`,windows:!0,text:`In a new Desktop file, connect to Mill_Warehouse and load one table. Then try to export a .pbids file from Data source settings. Learn shows Export PBIDS but has no Fabric warehouse example, so this is an experiment: if Export PBIDS is offered, close the file and open the .pbids; if it isn’t, record that in a problem note and go on to step 6.`,sources:[i(a.whConnect,`connect-using-power-bi`),i(a.pbids,`how-to-create-a-pbids-connection-file`)],checkpoint:`You know whether Export PBIDS was offered for this source, and, if it was, what opening the .pbids did.`},{id:`s6`,windows:!0,text:`In a new Desktop file, connect live to Sales Model in DP600-Dev and build one visual.`,sources:[i(a.liveConnect,`establish-a-power-bi-service-live-connection-to-the-published-semantic-model`)],checkpoint:`The status bar says you’re connected live to the semantic model.`},{id:`s7`,text:`In the browser, create a report in DP600-Test that uses Sales Model from DP600-Dev, and read what Build permission allows.`,sources:[i(a.sharedModels,`semantic-model-sharing-and-workspaces`),i(a.sharedModels,`build-permission-for-semantic-models`)],checkpoint:`The report in DP600-Test shows data from the model in DP600-Dev.`}],cleanup:[{id:`c1`,text:`Delete the .pbids file and the template from your computer, and delete the report you made in DP600-Test.`,sources:[i(a.pbids,`use-pbids-files-to-get-data`)]}]},{id:`L15`,order:15,title:`Batch winder and remote loom control: incremental refresh, large models, XMLA, OneLake integration`,goal:`Publish an Import model with an incremental refresh policy, use large semantic model storage format, inspect its partitions over the XMLA endpoint, and export its tables to OneLake.`,machineIds:[`batch-winder`,`wide-beam`,`remote-loom-control`,`shared-spool`],bulletIds:[`S2.5`,`S1.6`,`M2.5`,`P1.5`],platform:`windows`,minutes:105,prereqs:[`L02`,`L04`],before:`Needs Power BI Desktop and SQL Server Management Studio (SSMS) on Windows. The workspace connection URL is private to your tenant: never paste it into a problem note.`,steps:[{id:`s1`,windows:!0,text:`In Power BI Desktop, connect to Mill_Warehouse in Import mode and choose the staging orders table. Its sample orders are dated in the first half of 2026.`,sources:[i(a.whConnect,`connect-using-power-bi`)],checkpoint:`Power Query Editor shows the orders table.`},{id:`s2`,windows:!0,text:`Learn expects a Date/Time column; this table’s order date is a date, so change its type to Date/Time in Power Query first. Then create RangeStart and RangeEnd with values a few months apart inside the first half of 2026. If the incremental refresh slider later stays disabled, report it.`,sources:[i(a.incremental,`filter-data`),i(a.incremental,`create-parameters`)],checkpoint:`Both parameters appear in the Queries pane with the Date/Time type.`},{id:`s3`,windows:!0,text:`Filter the date column with RangeStart and RangeEnd, using “equal to” on only one of them, then Close & Apply.`,sources:[i(a.incremental,`filter-data`)],checkpoint:`The table loads only rows inside your parameter range.`},{id:`s4`,windows:!0,text:`Define an incremental refresh policy on the table: archive at least 2 years (so the 2026 orders are kept) and refresh a shorter period.`,sources:[i(a.incremental,`define-policy`)],checkpoint:`The policy dialog’s summary describes both periods.`,trapPairId:`archive-vs-refresh-period`,trapNote:`The archive (store) period is how much history the model keeps; the refresh period is what each refresh reloads.`},{id:`s6`,text:`Before you publish, set DP600-Dev’s default storage format to large semantic model storage format, so the model gets it from its first refresh (Learn advises enabling it before the first refresh).`,sources:[i(a.workspaces,`default-storage-format`),i(a.largeModels,`set-default-storage-format`),i(a.incremental,`save-and-publish-to-the-service`)],checkpoint:`After you publish, the model’s settings show large semantic model storage format as on.`},{id:`s5`,windows:!0,text:`Publish to DP600-Dev, then refresh the model in the service.`,sources:[i(a.incremental,`save-and-publish-to-the-service`),i(a.incremental,`refresh-model`)],checkpoint:`The refresh history shows a completed refresh.`},{id:`s7`,text:`Copy the workspace connection URL from workspace settings. Keep it private.`,sources:[i(a.xmla,`to-get-the-workspace-connection-url`)],checkpoint:`You have a connection URL that starts with powerbi://.`},{id:`s8`,windows:!0,text:`Connect to the workspace with SSMS and expand your model’s orders table partitions.`,sources:[i(a.xmla,`connect-to-a-workspace-by-using-ssms`)],checkpoint:`Object Explorer lists your model, and the orders table’s Partitions dialog lists the partitions the service created.`,trapPairId:`xmla-read-vs-readwrite`,trapNote:`Browsing and querying need read; changing metadata or refreshing partitions needs read-write.`},{id:`s9`,optional:!0,windows:!0,text:`Script the model or one table as TMSL from SSMS and read it. Scripting metadata needs the XMLA endpoint set to Read Write (read-only is the default); if scripting fails, note it. Don’t run changes you don’t understand.`,sources:[i(a.xmla,`connect-with-ssms`),i(a.xmla,`enable-xmla-read-write`)],checkpoint:`A query window opens with the TMSL script.`},{id:`s10`,text:`Turn on OneLake integration in the model’s settings, then refresh the model. Learn lists Premium P and Fabric F SKUs and needs the tenant setting “Semantic models can export data to OneLake”; if the option is missing or greyed out, report it.`,sources:[i(a.smOneLake,`enable-onelake-integration`),i(a.smOneLake,`refresh-model`)],checkpoint:`The refresh history shows an entry on the OneLake integration tab.`,trapPairId:`onelake-availability-vs-integration`,trapNote:`This exports an Import model’s tables to OneLake; Lab 6 made eventhouse data available in OneLake.`},{id:`s11`,text:`In Mill_Lakehouse, create a shortcut to the model’s exported Delta tables.`,sources:[i(a.smOneLake,`shortcuts`),i(a.smOneLake,`explore-export-files`)],checkpoint:`The shortcut shows the exported tables.`}],cleanup:[{id:`c1`,text:`Turn OneLake integration off, delete the shortcut, and delete the Import model and its report from DP600-Dev.`,sources:[i(a.smOneLake,`enable-onelake-integration`)]},{id:`c2`,text:`Course cleanup, when every lab you plan to do is finished: remove DP600-Test and DP600-Dev (Workspace settings, then remove the workspace). When the trial ends, its workspaces move to Pro and non-Power BI Fabric items such as lakehouses, notebooks, and pipelines become inactive.`,sources:[r(`21-implement-cicd`,`clean-up`),i(a.trial,`when-your-fabric-trial-ends`)]}]}],f=e({LABS_PARTIAL:()=>g,LABS_UNCOVERED:()=>h,allLabs:()=>p,bulletsCovered:()=>v,labById:()=>m,labMinutes:()=>_,labsForMachine:()=>y,machineLabPlatform:()=>b}),p=[...s,...l,...d].sort((e,t)=>e.order-t.order),m=new Map(p.map(e=>[e.id,e])),h={},g={"M1.4":`Applying a label needs Microsoft Purview sensitivity labels published in your tenant. Lab 12 asks you to record it if none are available.`,"M1.3":`Testing CLS and what another user sees needs a second account in your organization; those steps are optional. Semantic model OLS needs Power BI Desktop (Windows).`,"M1.2":`Sharing an item with someone else needs a second account; without one, Lab 11 only shows the share options.`},_=p.reduce((e,t)=>e+t.minutes,0);function v(){return new Set(p.flatMap(e=>e.bulletIds))}function y(e){return p.filter(t=>t.machineIds.includes(e))}function b(e){let t=new Set(y(e).map(e=>e.platform));if(t.size!==0)return t.size===1?[...t][0]:`mixed`}export{f as a,y as i,p as n,m as r,g as t};